UPDATE  tdm34_role_allc_detail
   SET  tdm34_appr_id = #{apprId}
 WHERE  tdm34_role_allc_detail_id = #{roleAllcDetailId}
   AND  EXISTS ( SELECT 1 FROM tdm30_role_allc
                  WHERE tdm30_role_allc_id = tdm34_role_allc_id
                    AND tdm30_company_id = #{companyId} )

UPDATE  tdm31_role_desc
   SET  tdm31_appr_id = #{apprId}
 WHERE  tdm31_role_desc_id = #{roleDescId}
   AND  tdm31_company_id = #{companyId}

UPDATE  tdm31_role_desc
   SET  tdm31_work_date = CASE WHEN #{on} THEN f_sysdate() ELSE NULL END
 WHERE  tdm31_role_desc_id = #{roleDescId}
   AND  tdm31_company_id = #{companyId}

